import { BOARD_SIZES, isBoardSize } from '../boardCode.ts';
import type { BoardSize } from '../boardCode.ts';
import { MAX_MOVES } from '../transitions.ts';

export const STORAGE_KEY = 'neon-pairs.preferences.v1';
export type Preferences = Readonly<{
  size: BoardSize;
  bests: Readonly<Partial<Record<BoardSize, number>>>;
}>;

const emptyPreferences = (): Preferences => ({ size: 4, bests: {} });

export function readPreferences(): Preferences {
  try {
    const text = localStorage.getItem(STORAGE_KEY);
    if (text === null) return emptyPreferences();
    const value: unknown = JSON.parse(text);
    if (typeof value !== 'object' || value === null) return emptyPreferences();
    const size = 'size' in value && isBoardSize(value.size) ? value.size : 4;
    const bests: Partial<Record<BoardSize, number>> = {};
    if ('bests' in value && typeof value.bests === 'object' && value.bests !== null) {
      for (const side of BOARD_SIZES) {
        const best: unknown = Reflect.get(value.bests, String(side));
        if (typeof best === 'number' && Number.isSafeInteger(best) && best >= 0 && best <= MAX_MOVES) {
          bests[side] = best;
        }
      }
    }
    return { size, bests };
  } catch {
    return emptyPreferences();
  }
}

export function savePreferences(preferences: Preferences): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(preferences));
  } catch {
    // Preferences are optional; the current session remains playable.
  }
}
import { useCallback, useEffect, useRef } from 'react';
import type { RefObject } from 'react';
import { advanceGame } from '../transitions.ts';
import type { Session } from './sessionTypes.ts';

export function useActiveClock(
  current: RefObject<Session>,
  publish: (session: Session) => void,
  dealId: number,
) {
  const anchor = useRef(performance.now());
  const visible = useRef(!document.hidden);
  const generation = useRef(0);

  const synchronize = useCallback(() => {
    const now = performance.now();
    const session = current.current;
    const elapsed = Math.max(0, now - anchor.current);
    anchor.current = now;
    if (!visible.current || session.paused) return;
    const game = advanceGame(session.game, elapsed);
    if (game !== session.game) publish({ ...session, game });
  }, [current, publish]);

  const invalidate = useCallback(() => {
    generation.current += 1;
    anchor.current = performance.now();
    visible.current = !document.hidden;
  }, []);

  useEffect(() => {
    const token = generation.current;
    let frame = 0;
    const tick = () => {
      if (token !== generation.current) return;
      synchronize();
      frame = requestAnimationFrame(tick);
    };
    const visibilityChanged = () => {
      if (token !== generation.current) return;
      synchronize();
      visible.current = !document.hidden;
    };
    frame = requestAnimationFrame(tick);
    document.addEventListener('visibilitychange', visibilityChanged);
    return () => {
      generation.current += 1;
      cancelAnimationFrame(frame);
      document.removeEventListener('visibilitychange', visibilityChanged);
    };
  }, [dealId, synchronize]);

  return { synchronize, invalidate };
}

